<script lang="ts">
 import LibrarySubfilters from './LibrarySubfilters.svelte';
 import {onMount} from 'svelte';import {catalogApi,type CatalogManifest} from '$lib/api/catalog';import {libraryPreferencesApi} from '$lib/api/libraryPreferences';import {libraryPreferences,libraryFilters,type LibraryFilters,type LibraryKind,type LibrarySearch,type Favorite} from '$lib/rules/library';import CatalogRecordView from './CatalogRecordView.svelte';
 let kind:LibraryKind='options';let query='';let edition='2024';let scope='official';let source='';let type='';let rows:any[]=[];let manifest:CatalogManifest|null=null;let prefs=libraryPreferences(null);let error='';let busy=false;let saving=false;let selected:Favorite|null=null;let tab='search';let filters:LibraryFilters={};
 onMount(async()=>{try{[manifest,prefs]=await Promise.all([catalogApi.manifest(),libraryPreferencesApi.get()]);await search(false);}catch(cause){error=cause instanceof Error?cause.message:'No se pudo abrir la biblioteca.';}});
 const kindLabels={monsters:'Monstruos',items:'Objetos',options:'Personajes',spells:'Hechizos'};
 function criteria():LibrarySearch{return {kind,query,edition,scope,source,type,filters:libraryFilters(filters)};}
 async function search(remember=true){if(busy)return;busy=true;error='';try{const requested=criteria();const found=await catalogApi.librarySearch(requested);if(JSON.stringify(requested)!==JSON.stringify(criteria()))return;rows=found;if(remember)prefs=await libraryPreferencesApi.change({recent:requested});}catch(cause){error=cause instanceof Error?cause.message:'No se pudo buscar.';}finally{busy=false;}}
 async function favorite(row:Favorite){if(saving)return;saving=true;error='';try{prefs=await libraryPreferencesApi.change({favorite:row});}catch(cause){error=cause instanceof Error?cause.message:'No se pudo guardar el favorito.';}finally{saving=false;}}
 function repeat(row:LibrarySearch){({kind,query,edition,scope,source,type}=row);filters=libraryFilters(row.filters);tab='search';search(false);}
</script>
<div class="space-y-3 text-neutral">
 <nav class="flex gap-1" aria-label="Biblioteca personal">{#each [['search','Buscar'],['favorites','Favoritos'],['recent','Recientes']] as [id,label]}<button class="btn btn-sm flex-1 {tab===id?'btn-dnd':''}" on:click={()=>tab=id}>{label}</button>{/each}</nav>
 {#if error}<p role="alert" class="text-error text-sm">{error}</p>{/if}
 {#if selected}<div class="border-2 border-secondary rounded p-3 space-y-2"><button class="btn btn-sm" on:click={()=>selected=null}>← Volver a los resultados</button><CatalogRecordView kind={selected.kind} entryKey={selected.key}/></div>
 {:else if tab==='search'}
 <form class="space-y-2" on:submit|preventDefault={()=>search()}><label class="block text-sm">Categoría<select class="select select-bordered select-sm w-full" bind:value={kind} on:change={()=>{type='';filters={};rows=[];}}><option value="options">Personajes: clases, especies y dotes</option><option value="spells">Hechizos</option><option value="items">Objetos</option><option value="monsters">Monstruos</option></select></label><input aria-label="Buscar en biblioteca" class="input input-bordered input-sm w-full" bind:value={query} maxlength="100" placeholder="Nombre o palabra clave…"/>
 <div class="grid grid-cols-2 gap-2"><select aria-label="Edición" class="select select-bordered select-sm w-full" bind:value={edition}><option value="2024">Reglas 2024</option><option value="2014">Reglas 2014</option><option value="all">Todas / A5E</option></select><select aria-label="Contenido" class="select select-bordered select-sm w-full" bind:value={scope}><option value="official">Oficial</option><option value="third-party">Terceros</option><option value="playtest">Pruebas</option><option value="homebrew">Homebrew</option><option value="all">Todos</option></select></div>
 <select aria-label="Publicación" class="select select-bordered select-sm w-full" bind:value={source}><option value="">Todos los libros</option>{#each Object.values(manifest?.sourceLabels||{}).sort((a,b)=>a.name.localeCompare(b.name)) as book}<option value={book.key}>{book.name}</option>{/each}</select>
 {#if kind==='options'}<select aria-label="Tipo de opción" class="select select-bordered select-sm w-full" bind:value={type}><option value="">Todos los tipos</option>{#each [['class','Clases'],['subclass','Subclases'],['species','Especies'],['subspecies','Variantes'],['background','Trasfondos'],['feat','Dotes']] as [id,label]}<option value={id}>{label}</option>{/each}</select>{/if}
 {#if kind==='items'}<label class="block text-sm">Tipo de objeto<select class="select select-bordered select-sm w-full" bind:value={type} on:change={()=>filters={}}><option value="">Todos los objetos</option><option value="weapon">Armas</option><option value="armor">Armaduras y escudos</option><option value="consumable">Consumibles</option><option value="other">Otros objetos</option></select></label>{/if}
 <LibrarySubfilters {kind} {type} bind:filters/>
 <button class="btn btn-sm w-full" disabled={busy}>{busy?'Buscando…':'Buscar'}</button></form>
 <p class="text-xs">Hasta 60 resultados. Afiná el nombre o los filtros para encontrar una ficha.</p>{#each rows as row}<div class="flex gap-2 border-t border-primary/20 pt-2"><button class="flex-1 text-left min-w-0" on:click={()=>selected={kind,key:row.key,name:row.name}}><strong class="block text-sm">{row.name}</strong><span class="text-xs">{row.sourceLabel} · {row.edition}</span></button><button class="btn btn-xs" disabled={saving} aria-label={`Favorito ${row.name}`} aria-pressed={prefs.favorites.some(f=>f.kind===kind&&f.key===row.key)} on:click={()=>favorite({kind,key:row.key,name:row.name})}>{prefs.favorites.some(f=>f.kind===kind&&f.key===row.key)?'★':'☆'}</button></div>{/each}{#if !busy&&!rows.length}<p class="text-sm">Sin coincidencias.</p>{/if}
 {:else if tab==='favorites'}{#each prefs.favorites as row}<div class="flex gap-2 border-t border-primary/20 py-2"><button class="flex-1 text-left text-sm" on:click={()=>selected=row}>{row.name}<span class="block text-xs opacity-70">{kindLabels[row.kind]}</span></button><button class="btn btn-xs" disabled={saving} aria-label={`Quitar favorito ${row.name}`} on:click={()=>favorite(row)}>★</button></div>{/each}{#if !prefs.favorites.length}<p class="text-sm">Guardá fichas con la estrella para encontrarlas acá.</p>{/if}
 {:else}{#each prefs.recent as row}<button class="block w-full text-left border-t border-primary/20 py-2" on:click={()=>repeat(row)}><span class="text-sm font-semibold">{row.query||'Explorar catálogo'}</span><span class="block text-xs">{kindLabels[row.kind]} · {row.edition} · {row.scope}</span></button>{/each}{#if !prefs.recent.length}<p class="text-sm">Las búsquedas que hagas aparecerán acá.</p>{/if}{/if}
</div>
<style>.input,.select{color:#f7ecd8;background:#2d241c;}</style>
